import React, { useState } from 'react';

function App() {
  const [count, setCount] = useState(5);
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('');

  // Increment: also calls two methods
  const handleIncrement = () => {
    incrementValue();
    sayHello();
  };

  const incrementValue = () => {
    setCount(count + 1);
  };

  const sayHello = () => {
    alert("Hello! Member1");
  };

  const handleDecrement = () => {
    setCount(count - 1);
  };

  const sayWelcome = (msg) => {
    alert(msg);
  };

  const handleClick = () => {
    alert("I was clicked");
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const converted = amount * 80; // Assuming 1 Euro = ₹80
    alert(`Converting to ${currency} Amount is ${converted}`);
  };

  return (
    <div style={{ padding: '20px' }}>
      <div>{count}</div>
      <button onClick={handleIncrement}>Increment</button><br />
      <button onClick={handleDecrement}>Decrement</button><br />
      <button onClick={() => sayWelcome("welcome")}>Say welcome</button><br />
      <button onClick={handleClick}>Click on me</button>

      <h1 style={{ color: "green" }}>Currency Convertor!!!</h1>
      <form onSubmit={handleSubmit}>
        <label>Amount: </label>
        <input
          type="text"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        /><br />

        <label>Currency: </label>
        <input
          type="text"
          value={currency}
          onChange={(e) => setCurrency(e.target.value)}
        /><br />

        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

export default App;
